function createIcon(name: string, title: string) {
  const Icon = React.forwardRef<SVGSVGElement, IconProps>(function Icon(
    { size = 20, strokeWidth = 1.15, ...props },
    ref,
  ) {
    return (
      <svg
        ref={ref}
        width={size}
        height={size}
        viewBox="0 0 14 14"
        fill="none"
        stroke="currentColor"
        strokeWidth={strokeWidth}
        strokeLinecap="round"
        strokeLinejoin="round"
        role="img"
        aria-hidden={props["aria-label"] ? undefined : true}
        {...props}
      >
        {props["aria-label"] ? <title>{props["aria-label"]}</title> : null}
        {paths[name].map((d, i) => (
          <path key={i} d={d} />
        ))}
      </svg>
    );
  });
  Icon.displayName = title;
  return Icon;
}

